//discover/page.tsx
"use client";

import { useState, useEffect } from "react";
import { useSearchParams } from "next/navigation";
import { discoverMovies, addMovie, getMovies } from "@/lib/api";
import { discoverSongs, addSong, getSongs } from "@/lib/api";
import { useRouter } from "next/navigation";

export default function DiscoverPage() {
  const router = useRouter();
  const [query, setQuery] = useState("");
  const searchParams = useSearchParams();
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<any[]>([]);
  const [friendInput, setFriendInput] = useState("");
  const [initialized, setInitialized] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [activeItem, setActiveItem] = useState<any | null>(null);
  const [searchType, setSearchType] = useState<"movie" | "music">("movie");
  const [existingMovieIds, setExistingMovieIds] = useState<Set<string>>(
    new Set(),
  );
  const [existingSongIds, setExistingSongIds] = useState<Set<string>>(
    new Set(),
  );
  const typeFromUrl = searchParams.get("type") as "movie" | "music" | null;
  const searchQueryFromUrl = searchParams.get("q");

  useEffect(() => {
    const loadExisting = async () => {
      // 🎬 Movies
      const movies = await getMovies({ limit: 100 });
      const movieIds = new Set<string>(
        movies.map((m: any) => m.external_id as string),
      );
      setExistingMovieIds(movieIds);
    };

    loadExisting();
  }, []);

  useEffect(() => {
    const loadExisting = async () => {
      const songs = await getSongs({ limit: 100 });

      const songIds = new Set<string>(
        songs.map((s: any) => s.external_id).filter(Boolean),
      );

      setExistingSongIds(songIds);
    };

    loadExisting();
  }, []);

  useEffect(() => {
    if (!searchQueryFromUrl) return;

    const resolvedType =
      typeFromUrl === "music" || typeFromUrl === "movie"
        ? typeFromUrl
        : "movie";

    // 🧹 Clear stale UI before searching
    setResults([]);
    setLoading(true);

    setSearchType(resolvedType);
    setQuery(searchQueryFromUrl);

    search(searchQueryFromUrl, resolvedType).finally(() => {
      setInitialized(true);
      setLoading(false);
    });
  }, [searchQueryFromUrl, typeFromUrl]);

  const search = async (q: string, type: "movie" | "music") => {
    if (!q.trim()) return;
    setLoading(true);

    const data =
      type === "movie" ? await discoverMovies(q) : await discoverSongs(q);

    setResults(data);
    setLoading(false);
  };

  useEffect(() => {
    if (searchQueryFromUrl) {
      setQuery(searchQueryFromUrl); // optional but nice UX
      search(searchQueryFromUrl, searchType);
    }
  }, [searchQueryFromUrl]);

  useEffect(() => {
    // Clear previous search state when switching type
    setResults([]);
    setQuery("");
    setActiveItem(null);
  }, [searchType]);

  return (
    <main
      style={{
        minHeight: "100vh",
        background: "radial-gradient(circle at top, #111 0%, #000 60%)",
        color: "white",
        padding: "32px 16px",
      }}
    >
      <div style={{ maxWidth: 900, margin: "0 auto" }}>
        <div style={{ marginBottom: 32 }}>
          <h1 style={{ margin: 0, fontSize: 28 }}>🍿 WatchPop</h1>
          <p style={{ marginTop: 8, opacity: 0.7 }}>
            Discover movies and music for your WatchPop
          </p>
        </div>

        <button
          onClick={() => router.push("/")}
          style={{
            marginBottom: 16,
            background: "transparent",
            border: "1px solid #333",
            color: "#bbb",
            padding: "6px 12px",
            borderRadius: 20,
            cursor: "pointer",
            fontSize: 13,
          }}
        >
          ← Home
        </button>

        <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
          <button
            onClick={() => setSearchType("movie")}
            style={{
              padding: "6px 14px",
              borderRadius: 16,
              border: "1px solid #333",
              background: searchType === "movie" ? "#1976d2" : "transparent",
              color: searchType === "movie" ? "white" : "#bbb",
              cursor: "pointer",
              fontSize: 13,
            }}
          >
            🎬 Movies
          </button>

          <button
            onClick={() => setSearchType("music")}
            style={{
              padding: "6px 14px",
              borderRadius: 16,
              border: "1px solid #333",
              background: searchType === "music" ? "#1976d2" : "transparent",
              color: searchType === "music" ? "white" : "#bbb",
              cursor: "pointer",
              fontSize: 13,
            }}
          >
            🎵 Music
          </button>
        </div>

        <div
          style={{
            display: "flex",
            gap: 12,
            marginBottom: 32,
          }}
        >
          <input
            placeholder={
              searchType === "movie" ? "Search movies..." : "Search music..."
            }
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && query.trim()) {
                search(query, searchType);
              }
            }}
            style={{
              flex: 1,
              padding: "10px 14px",
              borderRadius: 10,
              border: "1px solid #333",
              background: "#0f0f0f",
              color: "white",
              fontSize: 14,
            }}
          />

          <button
            onClick={() => search(query, searchType)}
            style={{
              padding: "10px 18px",
              borderRadius: 10,
              background: "#1976d2",
              color: "white",
              border: "none",
              cursor: "pointer",
              fontWeight: 600,
            }}
          >
            Search
          </button>
        </div>

        {/*{loading && <p>Loading...</p>}*/}

        <div style={{ marginTop: 24 }}>
          {!initialized || loading ? (
            <p style={{ opacity: 0.6 }}>Searching {searchType}...</p>
          ) : (
            <>
              {searchType === "movie" &&
                results.map((movie, index) => {
                  const isAdded = existingMovieIds.has(movie.external_id);

                  return (
                    <div
                      key={`${movie.external_id}-${index}`}
                      style={{
                        display: "flex",
                        gap: 16,
                        alignItems: "flex-start",
                        padding: 16,
                        marginBottom: 20,
                        borderRadius: 14,
                        background: "#0b0b0b",
                        border: "1px solid #222",
                        boxShadow: "0 20px 40px rgba(0,0,0,0.6)",
                      }}
                    >
                      {movie.image_url && (
                        <img
                          src={movie.image_url}
                          alt={movie.title}
                          width={90}
                          style={{ borderRadius: 8, flexShrink: 0 }}
                        />
                      )}

                      <div>
                        <h3 style={{ margin: 0 }}>{movie.title}</h3>
                        <div style={{ fontSize: 13, opacity: 0.7 }}>
                          {movie.year}
                        </div>

                        <button
                          onClick={() => setActiveItem(movie)}
                          disabled={isAdded}
                          style={{
                            marginTop: 10,
                            padding: "8px 14px",
                            borderRadius: 8,
                            background: isAdded ? "#333" : "#1976d2",
                            color: "white",
                            border: "none",
                            cursor: isAdded ? "not-allowed" : "pointer",
                            fontWeight: 600,
                          }}
                        >
                          {isAdded ? "Added ✓" : "Add to WatchPop"}
                        </button>
                      </div>
                    </div>
                  );
                })}

              {searchType === "music" &&
                results.map((song, index) => {
                  const isAdded = existingSongIds.has(song.external_id);

                  return (
                    <div
                      key={`song-${song.track_id}-${index}`}
                      style={{
                        display: "flex",
                        gap: 16,
                        alignItems: "flex-start",
                        padding: 16,
                        marginBottom: 20,
                        borderRadius: 14,
                        background: "#0b0b0b",
                        border: "1px solid #222",
                        boxShadow: "0 20px 40px rgba(0,0,0,0.6)",
                      }}
                    >
                      {song.image_url && (
                        <img
                          src={song.image_url}
                          alt={song.title}
                          width={90}
                          style={{ borderRadius: 8, flexShrink: 0 }}
                        />
                      )}

                      <div>
                        <h3 style={{ margin: 0 }}>{song.title}</h3>
                        <div style={{ fontSize: 13, opacity: 0.7 }}>
                          {song.artist}
                        </div>

                        <button
                          onClick={() => setActiveItem(song)}
                          disabled={isAdded}
                          style={{
                            marginTop: 10,
                            padding: "8px 14px",
                            borderRadius: 8,
                            background: isAdded ? "#333" : "#1976d2",
                            color: "white",
                            border: "none",
                            cursor: isAdded ? "not-allowed" : "pointer",
                            fontWeight: 600,
                          }}
                        >
                          {isAdded ? "Added ✓" : "Add to WatchPop"}
                        </button>
                      </div>
                    </div>
                  );
                })}
            </>
          )}
        </div>
        {activeItem && (
          <div
            style={{
              position: "fixed",
              inset: 0,
              background: "rgba(0,0,0,0.6)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              zIndex: 50,
            }}
          >
            <div
              style={{
                background: "#111",
                padding: 20,
                width: 400,
                borderRadius: 8,
              }}
            >
              <h3>Add to WatchPop</h3>
              <p style={{ opacity: 0.7 }}>
                Who recommended <b>{activeItem.title}</b>?
              </p>

              <input
                placeholder="Friend names (comma-separated)"
                value={friendInput}
                onChange={(e) => setFriendInput(e.target.value)}
                style={{ width: "100%", padding: 8, marginTop: 10 }}
              />

              <div style={{ marginTop: 16, display: "flex", gap: 8 }}>
                <button
                  onClick={() => {
                    setActiveItem(null);
                    setFriendInput("");
                  }}
                >
                  Cancel
                </button>

                <button
                  disabled={saving}
                  onClick={async () => {
                    setSaving(true);

                    const friendTags = friendInput
                      .split(",")
                      .map((t) => t.trim())
                      .filter(Boolean); // ✅ ensures string[]

                    if (searchType === "movie") {
                      const data = await addMovie(
                        activeItem.external_id,
                        friendTags,
                      );
                      setExistingMovieIds((prev) =>
                        new Set(prev).add(activeItem.external_id),
                      );

                      setMessage(data.message);
                      setTimeout(() => setMessage(null), 3000);
                    }

                    if (searchType === "music") {
                      const data = await addSong(
                        activeItem.external_id,
                        friendTags,
                      );
                      setExistingSongIds((prev) =>
                        new Set(prev).add(activeItem.external_id),
                      );
                      setMessage(data.message);
                      setTimeout(() => setMessage(null), 3000);
                    }

                    setSaving(false);
                    setActiveItem(null);
                    setFriendInput("");
                  }}
                >
                  {saving ? "Saving..." : "Save"}
                </button>
              </div>
            </div>
          </div>
        )}

        {message && (
          <div
            style={{
              position: "fixed",
              bottom: 24,
              right: 24,
              padding: "12px 16px",
              borderRadius: 10,
              background: "#1b5e20",
              color: "#c8e6c9",
              border: "1px solid #2e7d32",
              boxShadow: "0 8px 24px rgba(0,0,0,0.4)",
              zIndex: 1000,
              maxWidth: 320,
            }}
          >
            {message}
          </div>
        )}
      </div>
    </main>
  );
}
